?INCLUDE 'sp5A_monologue'
sp5A_monologue.dialogstring_0684F5! `[BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme0]Will: When I regained[N]consciousness, I was[N]standing in a bizarre[N]palace.[FIN]I didn't have any memories[N]from after the parachutes[N]landed in the water…[N]But maybe everyone's safe.[END]`

?INCLUDE 'sp5A_phantom_ribber'
sp5A_phantom_ribber.dialogstring_068A1B! `[BOR:3][DLG:3,4][SIZ:D,2][PRT:@RetranslationTheme0]Will: This is something[N]strange, isn't it?[FIN][CLD][BOR:3][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme0]Even though I touched the[N]enemy, I haven't taken any[N]damage…[END]`

?INCLUDE 'sp5A_voice'
sp5A_voice.dialogstring_0696A5! `[BOR:3][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme0]Will: Oh? I feel a human[N]presence from the room to[N]the right…[END]`
sp5A_voice.dialogstring_069705! `[BOR:3][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme0]Will: Oh? I can hear a[N]weak voice coming from[N]somewhere…[FIN]`
sp5A_voice.dialogstring_0695AF! `[PRT:@dialogstring_069705][BOR:4][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme17]Mysterious voice: Vampires[N]live in this place…[FIN][BOR:4][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme17]The fountain of blood in[N]this palace produces[N]demons one by one…[END]`
sp5A_voice.dialogstring_0696D5! `[BOR:3][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme0]Will: Oh? I feel a human[N]presence from the room to[N]the left…[END]`

?INCLUDE 'sp5B_erik'
sp5B_erik.dialogstring_0688B6! `[BOR:3][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme3]Erik: Where is this? It's[N]bleak… It's lonely… Mom,[N]help me…[END]`

?INCLUDE 'sp5A_voice'
sp5A_voice.dialogstring_069612! `[PRT:@dialogstring_069705][BOR:4][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme17]Mysterious voice: The[N]fountain of blood is on[N]the lowest floor of the[N]palace…[FIN]There… With that stone…[N]Hurry, hur.rrr..ry…[END]`

?INCLUDE 'sp5B_lily'
sp5B_lily.dialogstring_068709! `[BOR:6][DLG:3,4][SIZ:D,1][PRT:@RetranslationTheme2]Lilly: Waah…!![PAU:14]`
sp5B_lily.dialogstring_068721! `[BOR:6][DLG:3,4][SIZ:D,2][PRT:@RetranslationTheme2]Lilly: Geez… Don't[N]surprise me…!![FIN][CLD][BOR:6][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme2]My heart nearly jumped out[N]of my chest because of[N]you, you know…!![END]`
sp5B_lily.dialogstring_068765! `[CLD][BOR:6][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme2]Lilly: I saw Erik in the[N]other room a moment ago,[N]but something was wrong.[WAI][N]His body was half[N]transparent. I could see[N]right through him.[WAI][N]I tried speaking to him,[N]but he couldn't hear me.[WAI][N]Let's stick together until[N]we figure out what's[N]happening.[END]`
sp5B_lily.dialogstring_06882D! `[BOR:6][DLG:3,4][SIZ:D,2][PRT:@RetranslationTheme2]Lilly: I'll borrow your[N]pocket, alright?[END]`
sp5B_lily.dialogstring_06885B! `[PAU:1E][BOR:6][DLG:3,4][SIZ:D,1][PRT:@RetranslationTheme2]Lilly: Alright. Let's go…[END]`

?INCLUDE 'sp5A_voice'
sp5A_voice.dialogstring_069672! `[PRT:@dialogstring_069705][BOR:4][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme17]Mysterious voice: The[N]purification stone in the[N]coffin…[END]`

?INCLUDE 'sp5B_kara'
sp5B_kara.dialogstring_06865E! `[BOR:7][DLG:3,4][SIZ:D,2][PRT:@RetranslationTheme1]Kara: Will… Where? Where[N]are you…??[END]`

?INCLUDE 'sp5C_key_coffin'
sp5C_key_coffin.dialogstring_0690A7! `[DEF][PRT:@RetranslationTheme0]Will: The coffins are [N]lined up...[PAL:0][END]`
sp5C_key_coffin.dialogstring_0690CF! `[BOR:3][DLG:3,15][SIZ:D,2][PRT:@RetranslationTheme0]Will: Isn't there an[N]opening in the coffin…?[FIN][CLD][DLG:3,15][SIZ:D,2]Lilly started talking[N]from Will's pocket.[FIN][BOR:6][DLG:3,15][SIZ:D,2][PRT:@RetranslationTheme2]Lilly: Wait a moment.[N]This coffin doesn't open?[FIN][CLD][BOR:6][DLG:3,13][SIZ:D,3][PRT:@RetranslationTheme2]I can open it if I go into[N]the hole. Shall I take a[N]look?[END]`
sp5C_key_coffin.dialogstring_069167! `[BOR:6][DLG:3,11][SIZ:D,4][PRT:@RetranslationTheme2]Lilly: That's strange…[N]There's a lock inside this[N]coffin. No wonder it[N]doesn't open, huh?[END]`

?INCLUDE 'sp5C_stone_coffin'
sp5C_stone_coffin.dialogstring_0692E2! `[DEF][PRT:@RetranslationTheme0]Will: The coffins are [N]lined up...[PAL:0][END]`
sp5C_stone_coffin.dialogstring_06930A! `[DLG:3,15][SIZ:D,2]Lilly started talking[N]from Will's pocket.[FIN][BOR:6][DLG:3,15][SIZ:D,2][PRT:@RetranslationTheme2]Lilly: This coffin[N]doesn't open?[FIN][CLD][BOR:6][DLG:3,13][SIZ:D,3][PRT:@RetranslationTheme2]I can open it if I go into[N]the hole. Shall I take a[N]look?[END]`
sp5C_stone_coffin.dialogstring_069377! `[BOR:6][DLG:3,15][SIZ:D,2][PRT:@RetranslationTheme2]Lilly: I found this weird[N]rock in the coffin.[FIN]`
sp5C_stone_coffin.dialogstring_0693B7! `[CLD][BOR:6][DLG:3,11][SIZ:D,4][PRT:@RetranslationTheme2]Lilly: I found this weird[N]rock in the coffin. But it[N]doesn't look like you have[N]room to carry it[AD][END]`
sp5C_stone_coffin.dialogstring_06939E! `[CLD][DLG:3,15][SIZ:D,2][SFX:0][DLY:9]Got the Purity Stone![PAU:78][END]`

?INCLUDE 'item_use_system'
item_use_system.dialogstring_039244! `[DLG:3,15][SIZ:D,2]Will holds up the[N]Purity Stone![FIN]`
item_use_system.dialogstring_03925F! `However, nothing happened![END]`

?INCLUDE 'sp5B_neil'
sp5B_neil.dialogstring_06898C! `[BOR:D][DLG:3,4][SIZ:D,1][PRT:@RetranslationTheme6]Neil: Ungh, ungh.[END]`

?INCLUDE 'sp5B_lance'
sp5B_lance.dialogstring_068930! `[BOR:3][DLG:3,4][SIZ:D,1][PRT:@RetranslationTheme4]Lance: Ungh, ungh.[END]`

?INCLUDE 'sp5D_fountain'
sp5D_fountain.dialogstring_0694AA! `[CLD][BOR:6][DLG:3,13][SIZ:D,3][PRT:@RetranslationTheme2]Lilly: Ah[AD]! It's a[N]fountain made of blood[AD][FIN]Could this have something[N]to do with that stone[N]we just found?[END]`

?INCLUDE 'item_use_system'
item_use_system.dialogstring_03926F! `[DLG:3,11][SIZ:D,4]The stone grows brighter[N]and disappears into the[N]fountain[AD][END]`

?INCLUDE 'sp5A_villagers'
sp5A_villagers.dialogstring_068B22! `[CLD][BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]You saved me! Thank you![WAI][N]I was taken here from[N]Freejia and transformed[N]into a demon.[FIN][CLD][DEF]Lilly speaks from inside[N]Will's pocket.[FIN][CLD][BOR:6][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme2]Lilly: What[AD]? Then some[N]of the demons here used[N]to be people[AD]?[END]`
sp5A_villagers.dialogstring_068BB6! `[CLD][BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]For a moment, I knew what[N]it felt like to be dying.[WAI][N]I never knew how badly I[N]wanted to live until I[N]almost couldn't.[WAI][N]It makes me wonder whether[N]the animals we eat feel[N]that same fear.[END]`
sp5A_villagers.dialogstring_068C33! `[CLD][BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]We used to be slave[N]merchants. We were[N]arrested for trafficking[N]people.[WAI][N]Then corrupt officials[N]sold us to vampires.[WAI][N]I suppose there is justice[N]in that, though I wish I'd[N]learned it another way.[END]`
sp5A_villagers.dialogstring_068CBD! `[CLD][BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]Good grief[AD] A beautiful[N]woman invited me here, and[N]look where that got me.[END]`
sp5A_villagers.dialogstring_068CF6! `[BOR:3][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme16]A handsome man asked me to[N]come, so I came here… I[N]still can't believe men![END]`
sp5A_villagers.dialogstring_068D29! `[CLD][BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]There's no doubt about it;[N]vampires sleep in these[N]coffins.[WAI][N]Those bastards are[N]planning something[N]horrible[AD][END]`
sp5A_villagers.dialogstring_068D7A! `[CLD][BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]A vampire husband and wife[N]rule this palace.[WAI][N]They bring people[N]here from all over and[N]transform them into[N]demons for labor.[END]`
sp5A_villagers.dialogstring_068DD0! `[CLD][BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]This palace is connected[N]to the lost continent[N]of Mu.[WAI][N]The vampire couple[N]has been searching for[N]something there.[END]`
sp5A_villagers.dialogstring_068E20! `[BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]If you'd arrived any[N]later, we'd have been[N]turned into demons too[AD][END]`
sp5A_villagers.dialogstring_068E67! `[CLD][BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]I overheard the vampires.[WAI][N]They said a Mystic Statue[N]is hidden somewhere on Mu.[END]`
sp5A_villagers.dialogstring_068EA9! `[CLD][BOR:3][DLG:3,11][SIZ:D,4][PRT:@RetranslationTheme16]I snatched a key from the[N]vampire woman. Here, take[N]it.[END]`
sp5A_villagers.dialogstring_068ED4! `[DLG:3,17][SIZ:D,1][SFX:0][DLY:9]Got the Seabed Palace Key![PAU:78][END]`
sp5A_villagers.dialogstring_068F02! `[DEF]I stole a key from the[N]vampire woman. I'd give[N]it to you, but you don't[N]have room to carry it[AD][END]`
sp5A_villagers.dialogstring_068F53! `[CLD][BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]There's a passage to the[N]continent of Mu on the[N]upper floor of the palace.[END]`
sp5A_villagers.dialogstring_068F89! `[BOR:3][DLG:3,4][SIZ:D,3][PRT:@RetranslationTheme16]What should we do after[N]being left in the middle[N]of the sea like this…?[END]`
sp5A_villagers.dialogstring_068FC0! `[BOR:3][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme16]What will happen to[N]everyone who was abducted[N]and brought to this[N]palace?[END]`

?INCLUDE 'item_use_system'
item_use_system.dialogstring_039179! `[DLG:3,15][SIZ:D,2]Will tries the[N]Seabed Palace Key.[FIN]`
item_use_system.dialogstring_0391B6! `The key makes an eerie[N]sound as it turns.[FIN]`
item_use_system.dialogstring_0391D9! `[DLG:3,15][SIZ:D,2]Lilly begins to speak[N]from your pocket.[FIN][CLD][BOR:6][DLG:3,13][SIZ:D,3][PRT:@RetranslationTheme2]The passage ahead of here[N]leads to the fantastic[N]continent of Mu, right?[END]`

?INCLUDE 'sp5E_passageway'
sp5E_passageway.dialogstring_069753! `[DEF]Lilly speaks from inside[N]Will's pocket.[FIN][CLD][BOR:6][DLG:3,4][SIZ:D,4][PRT:@RetranslationTheme2]Lilly: This passage goes[N]on forever[AD] Are we really[N]headed toward Mu?[END]`
